input.sparql:
SELECT ?point ?tsid WHERE {
  ?z brick:hasSubclassOf* ?z.
  ?point ref:hasExternalReference* ?x .
  ?point brick:hasLocation ?z2 ;
         brick:isATypeOf* brick:AirTemperatureSensor .
  ?point ref:hasTimeseriesId ?tsid .
}

SELECT ?z ?name WHERE {
  ?ref a brick:IFCReference ;
        ref:ifcName ?name .
  FILTER(?name = "Perimeter_bot_ZN_3")
  ?x ref:hasExternalReference ?ref .
  BIND(?x AS ?z)
}

SELECT ?z ?name WHERE {
  ?ref ref:ifcName ?name .
  FILTER(CONTAINS(?name,"Perimeter_bot"))
  ?x ref:hasExternalReference ?ref .
  BIND(?x AS ?z)
}

SELECT ?z ?label WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?label .
} LIMIT 20

SELECT ?z ?label WHERE {
  ?z a brick:Zone .
  OPTIONAL{?z rdfs:label ?label}
} ORDER BY ?z LIMIT 60

SELECT ?room ?zone WHERE {
  ?room brick:hasPart* ?z .
  ?room brick:isRoomOf ?zone .
  FILTER(CONTAINS(STR(?room),"F2"))
} LIMIT 20

SELECT ?zone ?name WHERE {
  ?ref a brick:IFCReference ;
        ref:ifcName ?name .
  ?zone ref:hasExternalReference ?ref .
}

SELECT ?zone ?name WHERE {
  ?zone ref:hasExternalReference ?ref .
  ?ref a brick:IFCReference ;
       ref:ifcName ?name .
}

SELECT ?room ?label ?zone WHERE {
  ?room rdfs:label ?label .
  FILTER(CONTAINS(?label,"Perimeter_bot_ZN_3"))
  OPTIONAL{ ?zone brick:hasRoom* ?room . FILTER(?zone != ?room)}
}

SELECT ?pt ?tsid WHERE {
  <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z02> brick:hasPoint* ?pt .
  ?pt a brick:AirTemperatureSensor .
  ?pt ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?tsid .
}
